use crate::aap::caps::http_client;
use crate::wasi::clocks::wall_clock;

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len());
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

/// Converts days since 1970-01-01 to (year, month, day) in the proleptic Gregorian calendar.
fn civil_from_days(days: u64) -> (u64, u64, u64) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }
    (y, m, d)
}

fn format_date(seconds: u64) -> String {
    let (y, m, d) = civil_from_days(seconds / 86_400);
    // Keep the date exactly 10 characters even for absurd clock values.
    let (y, m, d) = if y > 9999 { (9999, 12, 31) } else { (y, m, d) };
    let mut s = String::with_capacity(10);
    let digits = |s: &mut String, v: u64, width: usize| {
        let mut buf = [b'0'; 4];
        let mut v = v;
        for i in (0..width).rev() {
            buf[i] = b'0' + (v % 10) as u8;
            v /= 10;
        }
        for &c in &buf[..width] {
            s.push(c as char);
        }
    };
    digits(&mut s, y, 4);
    s.push('-');
    digits(&mut s, m, 2);
    s.push('-');
    digits(&mut s, d, 2);
    s
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started = now.seconds;
        let date = format_date(started);

        // Enrichment fetch (approved grant extension). The result is not used,
        // so the node's output is unchanged; transport failures are ignored.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&tick.reason));
        let _ = http_client::fetch(&url);

        RunInfo { date, started }
    }
}

export!(Node);
